def mirror_concat_rows(grid):
    """Each row concatenated with its own reverse: row[::-1] + row."""
    return [row[::-1] + row for row in grid]

def flipud(grid):
    """The grid with its rows in reverse order."""
    return grid[::-1]

def fliplr(grid):
    """The grid with each row reversed."""
    return [row[::-1] for row in grid]

def vtile_reflect3(grid):
    """The grid tiled vertically as flipud, original, flipud (3 tiles)."""
    return flipud(grid) + grid + flipud(grid)

